INSERT INTO reading_list (id, title, url, category, summary, rating, created_at) VALUES (1600000000001, '巴菲特1999年太阳谷演讲', 'https://www.berkshirehathaway.com/letters/1999.html', '投资经典', '巴菲特在互联网泡沫顶峰时拒绝参与科技股投机的经典论述，阐述了价值投资的核心原则和为什么不买看不懂的公司。', 5, NOW());
INSERT INTO reading_list (id, title, url, category, summary, rating, created_at) VALUES (1600000000002, '格雷厄姆《聪明的投资者》第8章', 'https://www.amazon.com/Intelligent-Investor-Definitive-Value-Investing/dp/0060555661', '投资经典', '市场先生寓言——格雷厄姆解释股价波动不是风险而是机会。价值投资最基础的哲学框架。', 5, NOW());
INSERT INTO reading_list (id, title, url, category, summary, rating, created_at) VALUES (1600000000003, '查理·芒格《人类误判心理学》', 'https://fs.blog/great-talks/psychology-human-misjudgment/', '投资经典', '芒格总结的25种认知偏误，理解这些是避免投资错误的起点。比任何技术分析都有用。', 5, NOW());
INSERT INTO reading_list (id, title, url, category, summary, rating, created_at) VALUES (1600000000004, '巴菲特2008年纽约时报文章：Buy American', 'https://www.nytimes.com/2008/10/17/opinion/17buffett.html', '投资经典', '金融危机最恐慌时巴菲特公开喊买入美股。事后证明这是十年一遇的买入时机。恐惧时贪婪的经典案例。', 5, NOW());
INSERT INTO reading_list (id, title, url, category, summary, rating, created_at) VALUES (1600000000005, '霍华德·马克斯《投资最重要的事》备忘录精选', 'https://www.oaktreecapital.com/insights/memo', '投资经典', '橡树资本创始人二十年投资备忘录合集。涵盖周期、风险、第二层思维。价值投资者必读。', 5, NOW());
INSERT INTO reading_list (id, title, url, category, summary, rating, created_at) VALUES (1600000000006, '彼得·林奇《One Up on Wall Street》核心框架', '', '投资经典', '林奇的"十倍股"寻找方法：从生活中发现好公司、PEG估值法、六类公司分类。适合普通投资者的实用框架。', 5, NOW());
INSERT INTO reading_list (id, title, url, category, summary, rating, created_at) VALUES (1600000000007, '塞斯·卡拉曼《安全边际》核心章节', '', '投资经典', '为什么安全边际是投资中最重要的概念。没有安全边际的投资就是投机。', 5, NOW());
INSERT INTO reading_list (id, title, url, category, summary, rating, created_at) VALUES (1600000000008, '巴菲特致股东信（2013年）——关于农地和纽约房产的寓言', 'https://www.berkshirehathaway.com/letters/2013ltr.pdf', '投资经典', '巴菲特用两笔简单投资解释：波动不是风险，永久性资本损失才是风险。', 5, NOW());
INSERT INTO reading_list (id, title, url, category, summary, rating, created_at) VALUES (1600000000009, '查理·芒格在南加州大学的演讲', 'https://www.youtube.com/watch?v=pqzcCfUgl4M', '投资经典', '芒格式智慧：逆向思考、多元思维模型、能力圈。\“告诉我我会死在哪里，我就永远不去那个地方。\”', 5, NOW());
INSERT INTO reading_list (id, title, url, category, summary, rating, created_at) VALUES (1600000000010, '大卫·斯文森《机构投资的创新之路》资产配置框架', '', '投资经典', '耶鲁大学捐赠基金传奇CIO的配置哲学。分散化、再平衡、另类资产——长期投资的机构级框架。', 5, NOW());
INSERT INTO reading_list (id, title, url, category, summary, rating, created_at) VALUES (1600000000011, '瑞·达利欧《经济机器是怎样运行的》', 'https://www.youtube.com/watch?v=PHe0bXAIuk0', '宏观框架', '30分钟理解宏观经济：信贷、利率、生产率、短期债务周期和长期债务周期。投资前必须理解的底层逻辑。', 5, NOW());
INSERT INTO reading_list (id, title, url, category, summary, rating, created_at) VALUES (1600000000012, 'BIS 2025年度经济报告', 'https://www.bis.org/publ/arpdf/ar2025e.htm', '宏观框架', '国际清算银行年度重磅报告。全球债务水平、金融稳定风险评估、货币政策传导机制分析。', 5, NOW());
INSERT INTO reading_list (id, title, url, category, summary, rating, created_at) VALUES (1600000000013, '达利欧《原则：应对变化中的世界秩序》核心框架', '', '宏观框架', '帝国兴衰周期、储备货币更替、内部秩序与混乱。500年历史视角下的投资启示。', 5, NOW());
