INSERT INTO reading_list (id, title, url, category, summary, rating, created_at) VALUES (1600000000015, '辜朝明《资产负债表衰退》核心理论', '', '宏观框架', '日本失落的三十年的真正原因——企业和个人同时去杠杆。货币政策在资产负债表衰退中失效。对当下中国有重要参考价值。', 5, NOW());
INSERT INTO reading_list (id, title, url, category, summary, rating, created_at) VALUES (1600000000016, '美联储：理解通胀预期的形成机制', 'https://www.federalreserve.gov/econres/notes/feds-notes/', '宏观框架', '美联储官方研究：通胀预期如何影响实际通胀。预期管理是现代央行的核心工具。', 5, NOW());
INSERT INTO reading_list (id, title, url, category, summary, rating, created_at) VALUES (1600000000017, '麦肯锡全球研究院：全球资产负债表报告', 'https://www.mckinsey.com/mgi/our-research/the-rise-and-rise-of-the-global-balance-sheet', '宏观框架', '全球资产净值、债务结构、生产率趋势。宏观配置的底层数据。', 5, NOW());
INSERT INTO reading_list (id, title, url, category, summary, rating, created_at) VALUES (1600000000018, '达利欧：去杠杆化的三种方式', '', '宏观框架', '漂亮去杠杆 vs 丑陋去杠杆。中国目前面临的是哪种？对资产价格的深远影响。', 5, NOW());
INSERT INTO reading_list (id, title, url, category, summary, rating, created_at) VALUES (1600000000019, 'IMF全球金融稳定报告最新一期', 'https://www.imf.org/en/Publications/GFSR', '宏观框架', '全球系统性风险排查、跨境资本流动监测、新兴市场脆弱性评估。', 5, NOW());
INSERT INTO reading_list (id, title, url, category, summary, rating, created_at) VALUES (1600000000020, 'Hyman Minsky金融 instability 假说入门', '', '宏观框架', '"稳定本身孕育着不稳定"。明斯基时刻——理解每一次金融危机的理论基石。', 5, NOW());
INSERT INTO reading_list (id, title, url, category, summary, rating, created_at) VALUES (1600000000021, '能源转型：IEA 世界能源展望年度报告', 'https://www.iea.org/reports/world-energy-outlook-2025', '行业深度', '清洁能源投资 vs 化石燃料投资、电气化率、关键矿产需求。理解能源行业未来十年格局的权威素材。', 5, NOW());
