INSERT INTO reading_list (id, title, url, category, summary, rating, created_at) VALUES (1600000000024, 'AI革命：从基础设施到应用层的投资逻辑', '', '行业深度', 'GPU→云服务→模型→应用。每一层的经济学和护城河不同。如何从投资角度定位AI产业链。', 5, NOW());
