INSERT INTO reading_list (id, title, url, category, summary, rating, created_at) VALUES (1600000000028, '互联网平台：网络效应的量化与衰退信号', '', '行业深度', '用户增长→变现→利润的S曲线。如何判断平台是否已经过了"黄金时代"。中美互联网估值差异的根源。', 5, NOW());
INSERT INTO reading_list (id, title, url, category, summary, rating, created_at) VALUES (1600000000029, '新能源：光伏产业链的过度竞争周期', '', '行业深度', '多晶硅→硅片→电池→组件。中国光伏的产能过剩如何影响全球定价。行业出清的信号和时机。', 5, NOW());
INSERT INTO reading_list (id, title, url, category, summary, rating, created_at) VALUES (1600000000030, '贵金属：央行购金潮的底层逻辑', '', '行业深度', '全球央行连续三年购金超1000吨。去美元化、储备多元化、地缘政治避险——这不是短期趋势。', 5, NOW());
