INSERT INTO reading_list (id, title, url, category, summary, rating, created_at) VALUES (1600000000036, '1998年LTCM崩盘', '', '市场复盘', '诺贝尔奖得主创建的量化对冲基金，杠杆率25:1，俄罗斯违约触发连锁崩盘。\“天才+高杠杆=灾难\”的终极案例。', 5, NOW());
INSERT INTO reading_list (id, title, url, category, summary, rating, created_at) VALUES (1600000000037, '2013年"缩减恐慌"(Taper Tantrum)', '', '市场复盘', '伯南克暗示缩减QE，新兴市场资本外逃，印度卢比和土耳其里拉暴跌。美联储一句话如何引发全球震荡。', 5, NOW());
INSERT INTO reading_list (id, title, url, category, summary, rating, created_at) VALUES (1600000000038, '2022年加密货币连环暴雷', '', '市场复盘', 'Luna→3AC→Celsius→FTX。杠杆、挪用客户资产、关联交易。"去中心化"的讽刺剧。', 5, NOW());
