INSERT INTO reading_list (id, title, url, category, summary, rating, created_at) VALUES (1600000000040, '日本失落的三十年：资产泡沫到通缩陷阱', '', '市场复盘', '1989年日经38915点→2009年7054点。土地神话破灭、银行僵尸化、零利率陷阱。中国能学到什么？', 5, NOW());
