INSERT INTO reading_list (id, title, url, category, summary, rating, created_at) VALUES (1600000000042, '中国货币政策工具箱全景', '', '中国专题', 'MLF、LPR、降准、PSL、结构性货币政策工具。理解中国央行"精准滴灌"的操作逻辑。', 5, NOW());
