INSERT INTO reading_list (id, title, url, category, summary, rating, created_at) VALUES (1600000000044, '中美脱钩：贸易、科技、金融的现实进展', '', '中国专题', '关税、芯片禁令、审计底稿、二级市场投资限制。脱钩不是二分法，是一张光谱。', 5, NOW());
