INSERT INTO reading_list (id, title, url, category, summary, rating, created_at) VALUES (1600000000046, '港股：离岸市场的定价逻辑', '', '中国专题', '港股=中国基本面+美元流动性+地缘风险溢价。AH溢价的原因和边界。港股什么时候便宜到值得买？', 5, NOW());
