INSERT INTO reading_list (id, title, url, category, summary, rating, created_at) VALUES (1600000000049, '中国能源安全战略与投资启示', '', '中国专题', '煤为基础、油为关键、新能源为方向。中国能源"不可能三角"如何影响大宗商品需求和定价。', 5, NOW());
